mapper.select:
SELECT INST_NM /* 기관명 */ , INST_NO /* 기관번호 */
FROM SAA000 /* 통합기관 */ WHERE UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND INST_NO = #{INST_NO}
ORDER BY INST_NO

SELECT DISTINCT A.BIZ_YR /* 사업연도 */ FROM SDA400 A /* 서비스사업 */ LEFT JOIN SDA420 B /* 서비스실행사업 */ ON A.SRVC_BIZ_NO = B.SRVC_BIZ_NO
WHERE 1=1 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.INST_NO = #{INST_NO}
ORDER BY A.BIZ_YR DESC

SELECT DISTINCT A.SRVC_EXCN_BIZ_NM , A.SRVC_EXCN_BIZ_NO , B.BIZ_YR , A.BIZ_BGNG_YMD , INST_NO , A.ALTMNT_GROUP_LCLAS_SE_CD , B.ALTMNT_GROUP_PRD_CL_SE_CD FROM SDA420 A /* 서비스실행사업 */ LEFT JOIN SDA400 B /* 서비스사업 */ ON A.SRVC_BIZ_NO = B.SRVC_BIZ_NO
WHERE 1=1 AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
ORDER BY BIZ_YR DESC, SRVC_EXCN_BIZ_NO DESC

