INSERT INTO AFA131 (
      COMPNO_CHC_TYPE_MNG_NO
    , COMPNO_CHC_TYPE_DTL_SN
    , COMPNO_TYPE_LCLAS_SE_CD
    , COMPNO_TYPE_MLSFC_SE_CD
    , COMPNO_TYPE_SCLAS_SE_CD
    , FRST_RGTR_ID
    , LAST_MDFR_ID
) VALUES

(
    #{item.COMPNO_CHC_TYPE_MNG_NO}
    , (SELECT NVL(MAX(COMPNO_CHC_TYPE_DTL_SN), 0) + #{i}+1 FROM AFA131
        WHERE COMPNO_CHC_TYPE_MNG_NO = #{item.COMPNO_CHC_TYPE_MNG_NO})
    , SUBSTR(#{item.COMPNO_TYPE_SCLAS_SE_CD},1,2)
    , SUBSTR(#{item.COMPNO_TYPE_SCLAS_SE_CD},1,4)
    , #{item.COMPNO_TYPE_SCLAS_SE_CD}
    , #{item.USER_ID}
    , #{item.USER_ID}
)

